pub(crate) fn render_projected_place_expr<'tcx>(tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, place: &mir::Place<'tcx>, resolver: &LocalNameResolver) -> Option<String> {
    if place.projection.is_empty() {
        return resolver.label_place(place);
    }
    let mut expr = resolver.label_local(place.local)?;
    let mut cursor_ty = local_decls[place.local].ty;
    let mut pending_downcast: Option<(VariantIdx, ty::Ty<'tcx>, bool)> = None;
    let mut expr_is_ref = false;
    for elem in place.projection.iter() {
        match elem {
            mir::ProjectionElem::Deref => {
                // Avoid eagerly materializing `*expr` in the rendered output.
                // Emitting explicit deref here interacts poorly with enum
                // downcast projection, producing `match *self` and moving out
                // of borrowed values. Instead, keep the base expression
                // unchanged and only advance the type cursor.
                cursor_ty = match cursor_ty.kind() {
                    ty::TyKind::Ref(_, inner, _) => {
                        expr_is_ref = true;
                        *inner
                    }
                    ty::TyKind::RawPtr(inner, _) => *inner,
                    _ => cursor_ty.builtin_deref(true)?,
                };
            }
            mir::ProjectionElem::Downcast(variant_name, variant_idx) => {
                let _ = variant_name;
                pending_downcast = Some((variant_idx, cursor_ty, expr_is_ref));
            }
            mir::ProjectionElem::Field(field_idx, field_ty) => {
                let field = if let Some(downcast) = pending_downcast.take() {
                    expr = render_downcast_field_expr(tcx, &expr, downcast.1, downcast.0, field_idx, downcast.2)?;
                    String::new()
                } else {
                    match cursor_ty.kind() {
                        ty::TyKind::Adt(adt, _) => {
                            if !adt.did().is_local() {
                                let tuple_like = adt.non_enum_variant().fields.iter().all(|f| f.name.to_string().chars().all(|c| c.is_ascii_digit()));
                                if tuple_like {
                                    return None;
                                }
                            }
                            let f = adt.non_enum_variant().fields.get(field_idx)?;
                            let name = f.name.to_string();
                            if name.chars().all(|c| c.is_ascii_digit()) {
                                field_idx.index().to_string()
                            } else {
                                name
                            }
                        }
                        ty::TyKind::Tuple(_) => field_idx.index().to_string(),
                        _ => return None,
                    }
                };
                if !field.is_empty() {
                    expr = format!("({expr}).{field}");
                }
                cursor_ty = field_ty;
            }
            mir::ProjectionElem::Index(local) => {
                let idx = resolver.label_local(local)?;
                expr = format!("{expr}[{idx}]");
                cursor_ty = match cursor_ty.kind() {
                    ty::TyKind::Array(inner, _) | ty::TyKind::Slice(inner) => *inner,
                    _ => cursor_ty,
                };
            }
            mir::ProjectionElem::OpaqueCast(..) | mir::ProjectionElem::UnwrapUnsafeBinder(..) => {}
            _ => return None,
        }
    }
    if let Some(downcast) = pending_downcast {
        let ty::TyKind::Adt(adt, _) = downcast.1.kind() else {
            return None;
        };
        if !adt.is_enum() {
            return None;
        }
        let enum_path = norm::path(tcx, adt.did());
        let variant = adt.variant(downcast.0);
        let variant_path = format!("{enum_path}::{}", variant.name);
        // Match directly on the expression to avoid introducing an extra shared borrow
        // that can propagate as `&T` into return bindings (e.g., `&usize` instead of `usize`).
        expr = format!("match {expr} {{ {variant_path} => (), _ => panic!(\"canon downcast projection mismatch\") }}");
    }
    Some(expr)
}

fn render_downcast_field_expr<'tcx>(
    tcx: TyCtxt<'tcx>,
    base_expr: &str,
    enum_ty: ty::Ty<'tcx>,
    variant_idx: VariantIdx,
    field_idx: FieldIdx,
    base_is_ref: bool,
) -> Option<String> {
    let ty::TyKind::Adt(adt, args) = enum_ty.kind() else {
        return None;
    };
    if !adt.is_enum() {
        return None;
    }
    let variant = adt.variant(variant_idx);
    let enum_path = norm::path(tcx, adt.did());
    let variant_path = format!("{enum_path}::{}", variant.name);
    let idx = field_idx.index();
    if idx >= variant.fields.len() {
        return None;
    }
    let bind_prefix = if base_is_ref { "ref " } else { "" };

    let bindings: Vec<String> = (0..variant.fields.len()).map(|i| format!("__canon_f{i}")).collect();
    let select = bindings[idx].clone();
    let pattern = match &variant.fields {
        fields if fields.is_empty() => variant_path.clone(),
        fields
            if fields.iter().all(|f| {
                let name = f.name.to_string();
                !name.is_empty() && !name.chars().all(|c| c.is_ascii_digit())
            }) =>
        {
            let named = fields
                .iter()
                .zip(bindings.iter())
                .map(|(f, b)| format!("{}: {bind_prefix}{b}", f.name))
                .collect::<Vec<_>>()
                .join(", ");
            format!("{variant_path} {{ {named} }}")
        }
        _ => {
            let tuple = bindings.iter().map(|b| format!("{bind_prefix}{b}")).collect::<Vec<_>>().join(", ");
            format!("{variant_path}({tuple})")
        }
    };

    // Match on the base expression to avoid moving out of borrowed enum values.
    // Always return the binding as-is (reference when base_is_ref is true).
    let safe_base = base_expr.strip_prefix('*').unwrap_or(base_expr);
    Some(format!("match {safe_base} {{ {pattern} => {select}, _ => panic!(\"canon downcast projection mismatch\") }}"))
}

pub(crate) fn mir_binop_token(op: mir::BinOp) -> Option<&'static str> {
    match op {
        mir::BinOp::Add => Some("+"),
        mir::BinOp::Sub => Some("-"),
        mir::BinOp::Mul => Some("*"),
        mir::BinOp::Div => Some("/"),
        mir::BinOp::Rem => Some("%"),
        mir::BinOp::BitXor => Some("^"),
        mir::BinOp::BitAnd => Some("&"),
        mir::BinOp::BitOr => Some("|"),
        mir::BinOp::Shl => Some("<<"),
        mir::BinOp::Shr => Some(">>"),
        mir::BinOp::Eq => Some("=="),
        mir::BinOp::Lt => Some("<"),
        mir::BinOp::Le => Some("<="),
        mir::BinOp::Ne => Some("!="),
        mir::BinOp::Ge => Some(">="),
        mir::BinOp::Gt => Some(">"),
        mir::BinOp::Cmp => None,
        mir::BinOp::Offset => None,
        mir::BinOp::AddUnchecked => Some("+"),
        mir::BinOp::SubUnchecked => Some("-"),
        mir::BinOp::MulUnchecked => Some("*"),
        mir::BinOp::ShlUnchecked => Some("<<"),
        mir::BinOp::ShrUnchecked => Some(">>"),
        mir::BinOp::AddWithOverflow => None,
        mir::BinOp::SubWithOverflow => None,
        mir::BinOp::MulWithOverflow => None,
    }
}

pub(crate) fn mir_unop_token(op: mir::UnOp) -> &'static str {
    match op {
        mir::UnOp::Not => "!",
        mir::UnOp::Neg => "-",
        mir::UnOp::PtrMetadata => "",
    }
}

pub(crate) fn mir_assign_stmt<'tcx>(
    tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, lhs: &mir::Place<'tcx>, rvalue: &mir::Rvalue<'tcx>, resolver: &LocalNameResolver, defined: &std::collections::HashSet<String>,
    suppressed_sentinel_names: &std::collections::HashSet<String>,
) -> Option<Stmt> {
    let lhs_place = lhs;
    let lhs = resolver.label_place(lhs_place)?;
    // If we cannot render the rvalue into a concrete expression, do NOT
    // silently collapse it to unit. That destroys type information and
    // propagates `()` into non-unit locals (Vec, Option, String, etc.),
    // leading to downstream type errors in emitted Rust.
    // Instead, return None so the caller can decide whether to
    // structurally suppress or handle the assignment.
    let mut rhs = match mir_rvalue_expr(tcx, local_decls, rvalue, resolver) {
        Some(expr) => expr,
        None => return None,
    };
    // If MIR expects a value but the rvalue produces a reference, insert a deref.
    let lhs_ty = local_decls[lhs_place.local].ty;
    let rhs_ty = rvalue.ty(local_decls, tcx);
    if let mir::Rvalue::Use(mir::Operand::Copy(place) | mir::Operand::Move(place)) = rvalue {
        let has_deref = place.projection.iter().any(|p| matches!(p, mir::ProjectionElem::Deref));
        if has_deref && !rhs.starts_with('*') && !matches!(lhs_ty.kind(), ty::TyKind::Ref(..)) {
            rhs = format!("*{rhs}");
        }
    }
    match (lhs_ty.kind(), rhs_ty.kind()) {
        (ty::TyKind::Ref(..), ty::TyKind::Ref(..)) => {}
        (_, ty::TyKind::Ref(_, inner, _)) => {
            let is_copy = tcx.type_is_copy_modulo_regions(TypingEnv::fully_monomorphized(), *inner);
            if is_copy && !rhs.starts_with('*') {
                rhs = format!("*{rhs}");
            }
        }
        (ty::TyKind::Ref(..), _) => {
            if !rhs.starts_with('&') {
                rhs = format!("&{rhs}");
            }
        }
        _ => {}
    }
    if assign_rhs_should_suppress(&rhs) {
        return None;
    }
    if lhs == "__ret" {
        // Do not allow panic-based synthetic initialization of __ret;
        // force canonical suppressed binding instead.
        if rhs.contains("panic!") {
            // Do not downgrade panic-based structural expressions to unit.
            // Preserve the diverging expression to maintain correct typing
            // and avoid propagating `()` into non-unit locals.
            return Some(Stmt::Assign { lhs, rhs });
        }
        return Some(Stmt::Assign { lhs, rhs });
    }
    if matches!(rvalue, mir::Rvalue::Use(mir::Operand::Constant(_))) {
        return Some(Stmt::Assign { lhs, rhs });
    }
    if !mir_guard::value_known(&rhs, defined, suppressed_sentinel_names) {
        return None;
    }
    Some(Stmt::Assign { lhs, rhs })
}

pub(crate) fn mir_field_access_stmt<'tcx>(tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, lhs: &mir::Place<'tcx>, rvalue: &mir::Rvalue<'tcx>, resolver: &LocalNameResolver) -> Option<Stmt> {
    let mir::Rvalue::Use(mir::Operand::Copy(place) | mir::Operand::Move(place)) = rvalue else {
        return None;
    };
    let (base, proj) = place.as_ref().last_projection()?;
    let mir::ProjectionElem::Field(field_idx, ty) = proj else {
        return None;
    };

    let base_ty = base.ty(local_decls, tcx).ty;
    if is_primitive_value_ty(base_ty) {
        return None;
    }

    let field = match base_ty.kind() {
        ty::TyKind::Adt(adt, _) if adt.is_struct() || adt.is_union() => {
            if !adt.did().is_local() {
                let tuple_like = adt.non_enum_variant().fields.iter().all(|f| f.name.to_string().chars().all(|c| c.is_ascii_digit()));
                if tuple_like {
                    return None;
                }
            }
            let f = adt.non_enum_variant().fields.get(field_idx)?;
            let name = f.name.to_string();
            if name.chars().all(|c| c.is_ascii_digit()) {
                field_idx.index().to_string()
            } else {
                name
            }
        }
        ty::TyKind::Adt(adt, _) if adt.is_enum() => {
            let downcast_idx = place.projection.iter().find_map(|elem| match elem {
                mir::ProjectionElem::Downcast(_, idx) => Some(idx),
                _ => None,
            })?;
            let f = adt.variant(downcast_idx).fields.get(field_idx)?;
            let name = f.name.to_string();
            if name.chars().all(|c| c.is_ascii_digit()) {
                field_idx.index().to_string()
            } else {
                name
            }
        }
        ty::TyKind::Tuple(_) => field_idx.index().to_string(),
        _ => return None,
    };
    Some(Stmt::FieldAccess { base: resolver.label_place_ref(base)?, field, dest: Some(resolver.label_place(lhs)?) })
}

pub(crate) fn mir_struct_lit_stmt<'tcx>(tcx: TyCtxt<'tcx>, lhs: &mir::Place<'tcx>, rvalue: &mir::Rvalue<'tcx>, resolver: &LocalNameResolver) -> Option<Stmt> {
    let mir::Rvalue::Aggregate(kind, operands) = rvalue else {
        return None;
    };
    let mir::AggregateKind::Adt(adt_did, variant_idx, _, _, _) = &**kind else {
        return None;
    };
    let adt = tcx.adt_def(*adt_did);
    let variant = adt.variant(*variant_idx);
    if adt.is_enum() && variant.fields.is_empty() {
        return None;
    }
    let fields = variant.fields.iter().zip(operands.iter()).map(|(f, op)| Some((f.name.to_string(), mir_ops::mir_operand_label(tcx, op, resolver)?))).collect::<Option<Vec<_>>>()?;
    let ctor_path = if adt.is_enum() { format!("{}::{}", norm::path(tcx, *adt_did), variant.name) } else { norm::path(tcx, *adt_did) };
    Some(Stmt::StructLit { ty: TypeExpr::Path(ctor_path), fields, dest: Some(resolver.label_place(lhs)?) })
}

fn assign_rhs_should_suppress(rhs: &str) -> bool {
    rhs.contains("SizedTypeProperties") || rhs.contains("std::alloc::Global") || rhs.contains("alloc::Global")
}

fn mir_rvalue_expr<'tcx>(tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, rvalue: &mir::Rvalue<'tcx>, resolver: &LocalNameResolver) -> Option<String> {
    match rvalue {
        mir::Rvalue::Use(op) => match op {
            mir::Operand::Copy(place) | mir::Operand::Move(place) => {
                if place.projection.is_empty() {
                    resolver.label_place(place)
                } else {
                    render_projected_place_expr(tcx, local_decls, place, resolver)
                }
            }
            // Constants should lower directly and not depend on local labeling.
            mir::Operand::Constant(c) => render_constant_operand_expr(tcx, c)
                .or_else(|| {
                    let raw = c.const_.to_string();
                    let s = raw.trim();
                    if s.is_empty() || is_forbidden_const_fragment(s) {
                        None
                    } else if let Some(rest) = s.strip_prefix("const ") {
                        let rest = rest.trim();
                        if rest.is_empty() || is_forbidden_const_fragment(rest) {
                            None
                        } else {
                            Some(rest.to_string())
                        }
                    } else {
                        Some(s.to_string())
                    }
                })
                .or_else(|| mir_ops::mir_operand_label(tcx, op, resolver)),
            _ => mir_ops::mir_operand_label(tcx, op, resolver),
        },
        mir::Rvalue::Ref(_, borrow_kind, place) => {
            let place = render_projected_place_expr(tcx, local_decls, place, resolver)?;
            Some(match borrow_kind {
                mir::BorrowKind::Mut { .. } => format!("&mut {place}"),
                _ => {
                    // Avoid introducing redundant shared-borrow layers when
                    // the projected place already renders as a reference-like
                    // expression (e.g., match-based enum projections). This
                    // prevents emitting `&__canon_fN` and downstream `&T` vs `T`
                    // mismatches (E0597, E0308).
                    if place.starts_with('&') || place.starts_with("match ") {
                        place
                    } else {
                        format!("&{place}")
                    }
                }
            })
        }
        mir::Rvalue::RawPtr(raw_ptr_kind, place) => {
            let place = render_projected_place_expr(tcx, local_decls, place, resolver)?;
            Some(if matches!(raw_ptr_kind, mir::RawPtrKind::Mut) { format!("&mut {place}") } else { format!("&{place}") })
        }
        mir::Rvalue::BinaryOp(op, boxed) => {
            let (lhs, rhs) = &**boxed;
            let lhs = mir_ops::mir_operand_label(tcx, lhs, resolver)?;
            let rhs = mir_ops::mir_operand_label(tcx, rhs, resolver)?;
            match *op {
                mir::BinOp::AddWithOverflow => Some(format!("({lhs}).overflowing_add({rhs})")),
                mir::BinOp::SubWithOverflow => Some(format!("({lhs}).overflowing_sub({rhs})")),
                mir::BinOp::MulWithOverflow => Some(format!("({lhs}).overflowing_mul({rhs})")),
                _ => Some(format!("({lhs} {} {rhs})", mir_binop_token(*op)?)),
            }
        }
        mir::Rvalue::UnaryOp(op, operand) => Some(format!("({}{})", mir_unop_token(*op), mir_ops::mir_operand_label(tcx, operand, resolver)?)),
        mir::Rvalue::Cast(_, operand, ty) => Some(format!("({} as {})", mir_ops::mir_operand_label(tcx, operand, resolver)?, render_type_expr(tcx, &lower_ty(tcx, *ty)))),
        mir::Rvalue::Aggregate(kind, operands) => match &**kind {
            mir::AggregateKind::Adt(adt_did, variant_idx, _, _, _) => {
                let adt = tcx.adt_def(*adt_did);
                let variant = adt.variant(*variant_idx);
                if !variant.fields.is_empty() || !operands.is_empty() {
                    return None;
                }
                if adt.is_enum() {
                    Some(format!("{}::{}", norm::path(tcx, *adt_did), variant.name))
                } else {
                    Some(norm::path(tcx, *adt_did))
                }
            }
            mir::AggregateKind::Closure(def_id, args) => {
                mir_ops::closure_placeholder_expr_from_aggregate(tcx, *def_id, args)
            }
            mir::AggregateKind::Coroutine(def_id, args) => {
                mir_ops::closure_placeholder_expr_from_aggregate(tcx, *def_id, args)
            }
            mir::AggregateKind::CoroutineClosure(def_id, args) => {
                mir_ops::closure_placeholder_expr_from_aggregate(tcx, *def_id, args)
            }
            mir::AggregateKind::Tuple => {
                let elems = operands.iter().map(|op| mir_ops::mir_operand_label(tcx, op, resolver)).collect::<Option<Vec<_>>>()?;
                if elems.len() == 1 {
                    Some(format!("({},)", elems[0]))
                } else {
                    Some(format!("({})", elems.join(", ")))
                }
            }
            mir::AggregateKind::Array(_) => {
                let elems = operands.iter().map(|op| mir_ops::mir_operand_label(tcx, op, resolver)).collect::<Option<Vec<_>>>()?;
                Some(format!("[{}]", elems.join(", ")))
            }
            _ => None,
        },
        mir::Rvalue::Repeat(operand, count) => {
            let count = count.try_to_target_usize(tcx)?;
            Some(format!("[{}; {count}]", mir_ops::mir_operand_label(tcx, operand, resolver)?))
        }
        mir::Rvalue::Discriminant(place) => {
            let base = render_projected_place_expr(tcx, local_decls, place, resolver)?;
            Some(format!("{base} as isize"))
        }
        mir::Rvalue::CopyForDeref(place) => {
            let base = resolver.label_place(place)?;
            Some(format!("*{base}"))
        }
        _ => None,
    }
}

fn render_constant_operand_expr<'tcx>(tcx: TyCtxt<'tcx>, c: &mir::ConstOperand<'tcx>) -> Option<String> {
    if let Some(snippet) = tcx.sess.source_map().span_to_snippet(c.span).ok() {
        if let Some(normalized) = normalize_constant_text(c, &snippet) {
            return Some(normalized);
        }
    }

    let raw = c.const_.to_string();
    if let Some(normalized) = normalize_constant_text(c, &raw) {
        return Some(normalized);
    }
    let s = raw.trim();
    if !s.is_empty() && is_forbidden_const_fragment(s) {
        return Some("panic!(\"canon unresolved const fragment\")".to_string());
    }
    None
}

fn normalize_constant_text<'tcx>(c: &mir::ConstOperand<'tcx>, text: &str) -> Option<String> {
    let mut s = text.trim();
    if s.is_empty() || s == "_" {
        return None;
    }
    if let Some(rest) = s.strip_prefix("const ") {
        s = rest.trim();
    }
    if s.is_empty() || s == "_" {
        return None;
    }
    if is_forbidden_const_fragment(s) {
        return None;
    }

    if const_operand_is_str(c.const_.ty()) {
        if is_string_literal_text(s) {
            return Some(s.to_string());
        }
        if let Some(rest) = s.strip_prefix('&') {
            let rest = rest.trim();
            if is_string_literal_text(rest) {
                return Some(rest.to_string());
            }
        }
        return Some(format!("{s:?}"));
    }

    Some(s.to_string())
}

fn const_operand_is_str(mut ty: ty::Ty<'_>) -> bool {
    while let ty::TyKind::Ref(_, inner, _) = ty.kind() {
        ty = *inner;
    }
    matches!(ty.kind(), ty::TyKind::Str)
}

fn is_string_literal_text(s: &str) -> bool {
    s.starts_with('"') || s.starts_with("r\"") || s.starts_with("r#")
}

fn is_forbidden_const_fragment(s: &str) -> bool {
    let t = s.trim();
    t.contains('$') || matches!(t, ")" | "}" | "];" | ");" | "};" | "]")
}

fn is_primitive_value_ty(ty: ty::Ty<'_>) -> bool {
    matches!(ty.kind(), ty::TyKind::Bool | ty::TyKind::Char | ty::TyKind::Int(..) | ty::TyKind::Uint(..) | ty::TyKind::Float(..) | ty::TyKind::Str | ty::TyKind::Never)
}

pub(crate) fn strip_instance_generics(raw: &str) -> String {
    if !raw.contains("::<") {
        return raw.to_string();
    }
    let mut out = String::with_capacity(raw.len());
    let chars: Vec<char> = raw.chars().collect();
    let mut i = 0usize;
    while i < chars.len() {
        if i + 2 < chars.len() && chars[i] == ':' && chars[i + 1] == ':' && chars[i + 2] == '<' {
            i += 3;
            let mut depth = 1usize;
            while i < chars.len() && depth > 0 {
                match chars[i] {
                    '<' => depth += 1,
                    '>' => depth -= 1,
                    _ => {}
                }
                i += 1;
            }
            continue;
        }
        out.push(chars[i]);
        i += 1;
    }
    out
}

pub(crate) fn is_zero_arg_enum_ctor_expr_str(expr: &str) -> bool {
    let expr = strip_instance_generics(expr);
    expr == "std::option::Option::None" || expr == "core::option::Option::None" || expr == "Option::None"
}

pub(crate) fn is_internal_mir_const_repr(s: &str) -> bool {
    s.contains("{alloc") || s.starts_with("alloc") || s.contains("promoted[")
}

pub(crate) fn is_filtered_internal_call_path(path: &str) -> bool {
    let normalized = strip_instance_generics(path);
    let fmt_arguments_ctor = normalized.contains("fmt::Arguments::new");
    let fmt_rt_argument_ctor = normalized.contains("fmt::rt::Argument::new");
    matches!(
        normalized.as_str(),
        "std::hint::must_use"
            | "core::hint::must_use"
            | "std::io::_print"
            | "std::io::_eprint"
            | "core::fmt::Arguments::new"
            | "std::fmt::Arguments::new"
            | "core::fmt::Arguments::new_v1"
            | "std::fmt::Arguments::new_v1"
            | "core::fmt::Arguments::new_v1_formatted"
            | "std::fmt::Arguments::new_v1_formatted"
    ) || fmt_arguments_ctor
        || fmt_rt_argument_ctor
        || normalized.ends_with("::new_display")
        || normalized.ends_with("::branch")
        || normalized.ends_with("::from_residual")
        || normalized.ends_with("::from_output")
        || normalized.ends_with("::from_str")
        || normalized.contains("SizedTypeProperties")
        || normalized.contains("::__iterator_get_unchecked")
        || normalized.ends_with("::is_val_statically_known")
}

pub(crate) fn path_has_unresolved_generic(path: &str) -> bool {
    let bytes = path.as_bytes();
    for i in 0..bytes.len() {
        if bytes[i] != b'<' || i + 1 >= bytes.len() {
            continue;
        }
        let c = bytes[i + 1];
        if !c.is_ascii_uppercase() {
            continue;
        }
        if i + 2 >= bytes.len() {
            return true;
        }
        let next = bytes[i + 2];
        if next == b'>' || next == b',' || next.is_ascii_whitespace() {
            return true;
        }
    }
    false
}

use crate::types::Stmt;
use std::collections::HashSet;

pub fn structural_guard(stmt: &Stmt, defined: &HashSet<String>, suppressed_sentinel_names: &HashSet<String>) -> bool {
    match stmt {
        Stmt::Assign { .. } => {
            // Always allow assignments structurally.
            // Rejecting based on RHS defined-order causes user-named locals
            // like `symbols`, `fields`, `methods`, and `variants` to never
            // receive a structural binding when their RHS references
            // not-yet-defined values. Deterministic lowering must preserve
            // the assignment; type-checking will validate correctness later.
            true
        }
        Stmt::Call { .. } => {
            // Allow calls structurally; argument defined-ordering is handled
            // by deterministic lowering, not by rejecting the call.
            true
        }
        Stmt::FieldAccess { base, .. } => value_known(base, defined, suppressed_sentinel_names),
        Stmt::MethodCall { .. } => {
            // Allow method calls structurally; do not reject based on
            // transient defined-set ordering.
            true
        }
        Stmt::StructLit { fields, .. } => fields.iter().all(|(_, v)| value_known(v, defined, suppressed_sentinel_names)),
        Stmt::Match { .. } => true,
        _ => true,
    }
}

pub fn value_known(value: &str, defined: &HashSet<String>, suppressed_sentinel_names: &HashSet<String>) -> bool {
    value_known_with_mode(value, defined, suppressed_sentinel_names, false)
}

fn value_known_with_mode(value: &str, defined: &HashSet<String>, suppressed_sentinel_names: &HashSet<String>, allow_suppressed_inputs: bool) -> bool {
    if expr_uses_suppressed_sentinel(value, suppressed_sentinel_names) {
        return allow_suppressed_inputs;
    }
    if suppressed_sentinel_names.contains(value) {
        return allow_suppressed_inputs;
    }
    if is_synthetic_name(value) {
        return defined.contains(value);
    }
    defined.contains(value) || value == "__ret" || is_structural_expr(value)
}

pub fn emit_suppressed_binding(lhs: &str, defined: &mut HashSet<String>, suppressed_sentinel_names: &mut HashSet<String>, stmts: &mut Vec<Stmt>) -> bool {
    // Suppressed bindings are forbidden by invariant.
    // Do not introduce any synthetic sentinel assignments.
    // Structural lowering and deterministic return fallback
    // must handle incomplete paths instead.
    let _ = (lhs, defined, suppressed_sentinel_names, stmts);
    false
}

fn expr_uses_suppressed_sentinel(value: &str, suppressed_sentinel_names: &HashSet<String>) -> bool {
    value.split(|c: char| !(c == '_' || c.is_ascii_alphanumeric())).any(|tok| !tok.is_empty() && suppressed_sentinel_names.contains(tok))
}

fn is_synthetic_name(s: &str) -> bool {
    let s = s.strip_prefix('_').unwrap_or(s);
    let Some(rest) = s.strip_prefix('v') else {
        return false;
    };
    !rest.is_empty() && rest.chars().all(|c| c.is_ascii_digit())
}

fn is_structural_expr(value: &str) -> bool {
    value.contains("::")
        || value.starts_with('*')
        || value.contains('(')
        || value.contains(')')
        || value.contains('[')
        || value.contains(']')
        || value.contains('&')
        || value.contains(' ')
        || value.starts_with('"')
        || value.starts_with("b\"")
        || value.starts_with("br\"")
        || value.starts_with("&b\"")
        || value.starts_with("&br\"")
        || value.starts_with('\'')
        || value == "true"
        || value == "false"
        || value.chars().next().is_some_and(|c| c.is_ascii_digit() || c == '-')
}

use crate::types::{BasicBlock, Body, Stmt, Terminator};
use rustc_middle::mir;
use rustc_middle::ty::{self, TyCtxt};
use rustc_span::def_id::DefId;
use std::collections::HashSet;

use crate::capture::helpers::{lower_ty, render_type_expr};
use crate::capture::mir::analysis as mir_analysis;
use crate::capture::mir::expr as mir_expr;
use crate::capture::mir::guard as mir_guard;
use crate::capture::mir::passes as mir_passes;
// removed stale ensure_ret_bound import
use crate::capture::mir::patterns as mir_patterns;
use crate::capture::mir::patterns::MirOpKind;
use crate::capture::mir::terminator as mir_terminator;
use crate::capture::mir::util as mir_util;

use super::resolver::LocalNameResolver;

struct LowerPlan {
    resolver: LocalNameResolver,
    mir_to_emitted: Vec<Option<u32>>,
    switch_analysis: mir_analysis::SwitchAnalysis,
    call_feed_locals: HashSet<String>,
    defined: HashSet<String>,
    suppressed_sentinel_names: HashSet<String>,
    suppressed_dest_sentinels: Vec<Stmt>,
}

struct AssignLowerCtx<'a, 'tcx> {
    tcx: TyCtxt<'tcx>,
    local_decls: &'a mir::LocalDecls<'tcx>,
    resolver: &'a LocalNameResolver,
    call_feed_locals: &'a HashSet<String>,
    defined: &'a mut HashSet<String>,
    suppressed_sentinel_names: &'a mut HashSet<String>,
    stmts: &'a mut Vec<Stmt>,
    has_match_before_block: bool,
}

pub(crate) fn mir_body_structural(tcx: TyCtxt<'_>, def_id: DefId, param_names: &[String], returns_unit: bool) -> Body {
    let Some(local_def) = def_id.as_local() else {
        return Body::None;
    };
    if !tcx.is_mir_available(local_def) {
        return Body::None;
    }
    let body = match tcx.hir_body_const_context(local_def) {
        Some(rustc_hir::ConstContext::ConstFn) | Some(rustc_hir::ConstContext::Const { .. }) | Some(rustc_hir::ConstContext::Static(_)) => tcx.mir_for_ctfe(local_def),
        None => tcx.optimized_mir(local_def),
    };

    let mut plan = stage_build_plan(tcx, body, param_names);
    let draft = stage_emit_draft(tcx, body, returns_unit, &mut plan);
    let blocks = stage_normalize_draft(draft);
    stage_finalize_body_with_ret_fallback(tcx, def_id, returns_unit, blocks)
}

fn stage_build_plan<'tcx>(tcx: TyCtxt<'tcx>, body: &mir::Body<'tcx>, param_names: &[String]) -> LowerPlan {
    let resolver = LocalNameResolver::new(body, param_names);
    let switch_analysis = mir_analysis::analyze_switch_structure(body);
    // Temporarily disable call_feed_locals-based pruning.
    // Over-aggressive pruning can drop the only structural definition
    // of user-visible locals (e.g., symbols, fields, methods, variants,
    // result, target), while their uses (e.g., in __ret assignments)
    // remain, leading to E0425 undefined value errors despite zero
    // structural gaps.
    let call_feed_locals = std::collections::HashSet::new();
    let mut defined: HashSet<String> = param_names.iter().cloned().collect();
    let mut suppressed_sentinel_names: HashSet<String> = HashSet::new();
    let suppressed_dest_sentinels: Vec<Stmt> = mir_analysis::collect_suppressed_dest_sentinels(body, &resolver, &switch_analysis, &mut defined, &mut suppressed_sentinel_names)
        .into_iter()
        .filter(|s| !matches!(s, Stmt::Assign { lhs, .. } if lhs == "__ret"))
        .collect();

    // Never allow suppressed sentinel for __ret; return must be lowered structurally.
    let suppressed_dest_sentinels: Vec<Stmt> = suppressed_dest_sentinels.into_iter().filter(|s| !matches!(s, Stmt::Assign { lhs, .. } if lhs == "__ret")).collect();

    let mut mir_to_emitted: Vec<Option<u32>> = vec![None; body.basic_blocks.len()];
    let mut next_emitted = 0u32;
    for (mir_idx, bb) in body.basic_blocks.iter_enumerated() {
        if bb.is_cleanup {
            continue;
        }
        mir_to_emitted[mir_idx.as_usize()] = Some(next_emitted);
        next_emitted += 1;
    }

    LowerPlan { resolver, mir_to_emitted, switch_analysis, call_feed_locals, defined, suppressed_sentinel_names, suppressed_dest_sentinels }
}

fn stage_emit_draft<'tcx>(tcx: TyCtxt<'tcx>, body: &mir::Body<'tcx>, returns_unit: bool, plan: &mut LowerPlan) -> mir_passes::BodyDraft {
    let emitted_block_capacity = plan.mir_to_emitted.iter().filter(|slot| slot.is_some()).count();
    let mut emitted_blocks: Vec<mir_passes::EmittedBlock> = Vec::with_capacity(emitted_block_capacity);
    let mut pending_local_decls = build_local_decl_stmts(tcx, body, &plan.resolver);
    let mut locals_injected = false;

    // Do NOT pre-mark __ret as defined. It must be structurally assigned
    // by lowering or by deterministic fallback to avoid masked gaps.

    for (mir_idx, bb) in body.basic_blocks.iter_enumerated() {
        if bb.is_cleanup {
            continue;
        }
        if let Some(block) = mir_passes::emit_special_block(returns_unit, mir_idx.as_usize(), &emitted_blocks, &plan.switch_analysis, &mut plan.defined) {
            emitted_blocks.push(block);
            continue;
        }

        let mut stmts = stage_prepare_block_stmts();
        if !locals_injected && !pending_local_decls.is_empty() {
            stmts.append(&mut pending_local_decls);
            locals_injected = true;
        }
        stage_lower_block_statements(tcx, body, bb, &emitted_blocks, plan, &mut stmts);
        let term = stage_lower_block_terminator(tcx, body, returns_unit, mir_idx, bb, &emitted_blocks, plan, &mut stmts);
        // Do not emit suppressed __ret bindings at block end.
        // Missing return binding must be handled deterministically
        // by final fallback, not by suppressed sentinel.
        emitted_blocks.push(mir_passes::make_normal_block(stmts, term));
    }

    mir_passes::make_body_draft(emitted_blocks, std::mem::take(&mut plan.suppressed_dest_sentinels))
}

fn stage_normalize_draft(draft: mir_passes::BodyDraft) -> Vec<BasicBlock> {
    mir_passes::NormalizationPipeline::canonical().run(draft)
}

fn stage_prepare_block_stmts() -> Vec<Stmt> {
    Vec::new()
}

fn stage_lower_block_statements<'tcx>(tcx: TyCtxt<'tcx>, body: &mir::Body<'tcx>, bb: &mir::BasicBlockData<'tcx>, blocks: &[mir_passes::EmittedBlock], plan: &mut LowerPlan, stmts: &mut Vec<Stmt>) {
    let has_match_before_block = mir_passes::blocks_have_ret_match(blocks);
    for stmt in &bb.statements {
        let mut assign_ctx = AssignLowerCtx {
            tcx,
            local_decls: &body.local_decls,
            resolver: &plan.resolver,
            call_feed_locals: &plan.call_feed_locals,
            defined: &mut plan.defined,
            suppressed_sentinel_names: &mut plan.suppressed_sentinel_names,
            stmts,
            has_match_before_block,
        };
        lower_assign_statement(stmt, &mut assign_ctx);
    }
}

fn stage_lower_block_terminator<'tcx>(
    tcx: TyCtxt<'tcx>, body: &mir::Body<'tcx>, returns_unit: bool, mir_idx: mir::BasicBlock, bb: &mir::BasicBlockData<'tcx>, blocks: &[mir_passes::EmittedBlock], plan: &mut LowerPlan,
    stmts: &mut Vec<Stmt>,
) -> Terminator {
    let has_match_dest = mir_passes::blocks_have_ret_match(blocks) || stmts_have_ret_match(stmts);
    let has_ret_binding = mir_passes::blocks_have_ret_binding(blocks) || stmts_have_ret_binding(stmts);

    let Some(term_ref) = &bb.terminator else {
        return Terminator::None;
    };

    if let mir::TerminatorKind::Call { func, args, destination, target, .. } = &term_ref.kind {
        let term = mir_terminator::lower_call_terminator(
            tcx,
            &body.local_decls,
            func,
            args,
            destination,
            *target,
            &plan.resolver,
            &plan.mir_to_emitted,
            stmts,
            &mut plan.defined,
            &mut plan.suppressed_sentinel_names,
            has_match_dest,
        );
        // Do not emit suppressed __ret binding after call terminator.
        // Deterministic fallback handles missing return.
        term
    } else {
        let term = mir_terminator::lower_non_call_terminator(
            tcx,
            term_ref,
            returns_unit,
            &plan.resolver,
            &plan.mir_to_emitted,
            stmts,
            &mut plan.defined,
            has_ret_binding,
            has_match_dest,
            mir_idx.as_usize(),
            &plan.switch_analysis,
        );
        // Do not emit suppressed __ret binding after non-call terminator.
        // Deterministic fallback handles missing return.
        term
    }
}

fn stage_finalize_body(blocks: Vec<BasicBlock>) -> Body {
    Body::Blocks(blocks)
}

fn stage_finalize_body_with_ret_fallback(tcx: TyCtxt<'_>, def_id: DefId, returns_unit: bool, mut blocks: Vec<BasicBlock>) -> Body {
    // Always run deterministic return synthesis to eliminate suppressed __ret gaps.

    // Remove suppressed __ret assignments in every block before analysis.
    for bb in &mut blocks {
        bb.stmts.retain(|s| {
            !matches!(s,
                Stmt::Assign { lhs, rhs }
                if lhs == "__ret" && rhs.contains("canon suppressed binding")
            )
        });
    }

    // Strip all suppressed __ret bindings globally before synthesis.
    for bb in &mut blocks {
        bb.stmts.retain(|s| {
            !matches!(s,
                Stmt::Assign { lhs, rhs }
                if lhs == "__ret" && rhs.contains("canon suppressed binding")
            )
        });
    }

    // Do NOT synthesize a unit initializer for __ret in non-unit functions.
    // If no explicit __ret binding exists, we rely on upstream lowering to
    // provide a structurally valid return. Emitting `__ret = ()` here
    // pollutes non-unit functions with unit-typed return locals.
    if !returns_unit {
        for bb in &mut blocks {
            bb.stmts.retain(|s| {
                !matches!(s, Stmt::Assign { lhs, rhs } if lhs == "__ret" && rhs.trim() == "()")
            });
        }
        let mut has_ret_binding = false;
        for bb in &blocks {
            if bb.stmts.iter().any(|s| matches!(s, Stmt::Assign { lhs, .. } if lhs == "__ret")) {
                has_ret_binding = true;
                break;
            }
        }

        if !has_ret_binding {
            // Deterministic structural fallback: bind __ret to a diverging
            // expression so the return local exists with authoritative type
            // without fabricating a unit value.
            if let Some(first) = blocks.first_mut() {
                first.stmts.insert(0, Stmt::Assign { lhs: "__ret".to_string(), rhs: "panic!(\"canon missing return binding\")".to_string() });
            }
        }
    }

    // Do NOT synthesize unit defaults for non-unit functions.
    // Structural invariant: if a non-unit function reaches this stage
    // without an explicit __ret binding and return, we conservatively
    // emit a return of __ret only if it was already defined. We avoid
    // injecting `__ret = ()` as this pollutes emitted Rust with unit
    // assignments that break type correctness.

    // Ensure there is exactly one structural return. Preserve existing
    // structural __ret bindings if present; only synthesize if missing.
    let mut has_ret_binding = false;
    let mut has_return_stmt = false;
    for bb in &blocks {
        for s in &bb.stmts {
            if matches!(s, Stmt::Assign { lhs, .. } if lhs == "__ret") {
                has_ret_binding = true;
            }
            if matches!(s, Stmt::Return(_)) {
                has_return_stmt = true;
            }
        }
    }

    if !has_return_stmt {
        // If there is no explicit return, but __ret has been bound somewhere,
        // emit a final structural return of __ret without fabricating a unit default.
        if has_ret_binding {
            if let Some(last) = blocks.last_mut() {
                // If the function's return type is non-reference but __ret
                // was inferred as a reference due to projection binding,
                // normalize here by dereferencing once. This preserves
                // RETURN INTEGRITY without altering capture-time authority.
                // Do not inject `*__ret` here; preserve structural return.
                last.stmts.push(Stmt::Return(Some("__ret".to_string())));
            }
        }
    }

    // Structural invariant: no statements may appear after a Return within the same block.
    // Trim any trailing statements after the first Return to prevent
    // unreachable synthetic assignments like `__ret = ()` from being emitted
    // after `return __ret;`.
    for bb in &mut blocks {
        if let Some(pos) = bb.stmts.iter().position(|s| matches!(s, Stmt::Return(_))) {
            bb.stmts.truncate(pos + 1);
        }
    }

    let mut body = Body::Blocks(blocks);
    // Ensure MIR return place is materialized in CanonIR so that
    // local 0 (`__ret`) is recorded with its authoritative type.
    super::ret::ensure_ret_bound(&mut body, returns_unit);
    body
}

fn lower_assign_statement<'tcx>(stmt: &mir::Statement<'tcx>, ctx: &mut AssignLowerCtx<'_, 'tcx>) {
    let mir::StatementKind::Assign(boxed) = &stmt.kind else {
        return;
    };
    let (lhs, rvalue) = &**boxed;
    let lhs_name = ctx.resolver.label_place(lhs);

    match mir_patterns::dispatch_stmt_pattern(ctx.tcx, rvalue) {
        MirOpKind::FieldAccess => {
            if let Some(field_stmt) = mir_expr::mir_field_access_stmt(ctx.tcx, ctx.local_decls, lhs, rvalue, ctx.resolver) {
                if !mir_guard::structural_guard(&field_stmt, ctx.defined, ctx.suppressed_sentinel_names) {
                    if let Stmt::FieldAccess { dest: Some(dest), .. } = &field_stmt {
                        ctx.stmts.push(Stmt::Assign { lhs: dest.clone(), rhs: "panic!(\"canon structural guard failure\")".to_string() });
                        ctx.defined.insert(dest.clone());
                    }
                    return;
                }
                if let Stmt::FieldAccess { dest: Some(dest), .. } = &field_stmt {
                    ctx.defined.insert(dest.clone());
                }
                ctx.stmts.push(field_stmt);
                return;
            }
            // Fallback to generic assign lowering for projected field reads
            // that are representable as pure expressions (for example `(*self).score`).
        }
        MirOpKind::StructLit => {
            if let Some(struct_stmt) = mir_expr::mir_struct_lit_stmt(ctx.tcx, lhs, rvalue, ctx.resolver) {
                if !mir_guard::structural_guard(&struct_stmt, ctx.defined, ctx.suppressed_sentinel_names) {
                    if let Stmt::StructLit { dest: Some(dest), .. } = &struct_stmt {
                        ctx.stmts.push(Stmt::Assign { lhs: dest.clone(), rhs: "panic!(\"canon structural guard failure\")".to_string() });
                        ctx.defined.insert(dest.clone());
                    }
                    return;
                }
                if let Stmt::StructLit { dest: Some(dest), .. } = &struct_stmt {
                    ctx.defined.insert(dest.clone());
                }
                ctx.stmts.push(struct_stmt);
                return;
            }
            // Struct-literal pattern may still be representable as a generic
            // assignment expression (for example enum unit variants).
        }
        MirOpKind::OpaqueAggregate => {
            // Previously we returned early here, which meant the destination
            // local was labeled by the resolver but never structurally
            // defined. This leads to undefined `_vN` locals in emitted Rust.
            // Fall through to generic assignment lowering so the destination
            // receives a concrete definition.
        }
        MirOpKind::ZeroArgEnumCtor => {
            if let Some(assign_stmt) = mir_expr::mir_assign_stmt(ctx.tcx, ctx.local_decls, lhs, rvalue, ctx.resolver, ctx.defined, ctx.suppressed_sentinel_names) {
                if mir_guard::structural_guard(&assign_stmt, ctx.defined, ctx.suppressed_sentinel_names) {
                    if let Stmt::Assign { lhs, .. } = &assign_stmt {
                        ctx.defined.insert(lhs.clone());
                    }
                    ctx.stmts.push(assign_stmt);
                } else if let Some(lhs_name) = lhs_name.clone() {
                    if lhs_name != "__ret" {
                        ctx.stmts.push(Stmt::Assign { lhs: lhs_name.clone(), rhs: "panic!(\"canon structural guard failure\")".to_string() });
                        ctx.defined.insert(lhs_name.clone());
                    }
                }
            } else if let Some(lhs_name) = lhs_name.clone() {
                if lhs_name != "__ret" {
                    ctx.stmts.push(Stmt::Assign { lhs: lhs_name.clone(), rhs: "panic!(\"canon structural guard failure\")".to_string() });
                    ctx.defined.insert(lhs_name.clone());
                }
            }
            return;
        }
        MirOpKind::ConstUse => {}
        MirOpKind::ArrayAggregate => {
            if let Some(lhs_name) = lhs_name.as_ref()
                && ctx.defined.contains(lhs_name)
            {
                return;
            }
        }
        MirOpKind::Assign => {}
    }

    if let Some(assign_stmt) = mir_expr::mir_assign_stmt(ctx.tcx, ctx.local_decls, lhs, rvalue, ctx.resolver, ctx.defined, ctx.suppressed_sentinel_names) {
        // Do NOT allow structural_guard to suppress plain assignments.
        // Suppressing here causes temporaries (_vN) to be referenced later
        // without ever being structurally defined, leading to E0425.
        if let Stmt::Assign { lhs, .. } = &assign_stmt {
            ctx.defined.insert(lhs.clone());
        }
        ctx.stmts.push(assign_stmt);
    } else if let Some(lhs_name) = lhs_name {
        // Ensure every non-__ret local receives a structural definition.
        // This prevents undefined temporary locals in emitted Rust.
        if lhs_name != "__ret" {
            panic!("canon-capture invariant violation: unresolved assignment lowering lhs={lhs_name:?} rvalue={rvalue:?}");
        }
    }

    // Structural safety net: if we resolved a user-visible local name
    // but no statement above inserted it into `defined`, emit a
    // deterministic placeholder binding. This guarantees that
    // user-named locals like `symbols`, `fields`, `methods`,
    // `variants`, `result`, or `target` are never referenced
    // without a structural definition.
    if let Some(lhs_name) = ctx.resolver.label_place(lhs) {
        if lhs_name != "__ret" && !ctx.defined.contains(&lhs_name) {
            panic!("canon-capture invariant violation: local undefined after lowering lhs={lhs_name:?} rvalue={rvalue:?}");
        }
    }
}

fn stmts_have_ret_match(stmts: &[Stmt]) -> bool {
    stmts.iter().any(|stmt| matches!(stmt, Stmt::Match { dest: Some(dest) } if dest == "__ret"))
}

fn stmts_have_ret_binding(stmts: &[Stmt]) -> bool {
    stmts.iter().any(mir_util::stmt_defines_ret)
}

fn build_local_decl_stmts<'tcx>(tcx: TyCtxt<'tcx>, body: &mir::Body<'tcx>, resolver: &LocalNameResolver) -> Vec<Stmt> {
    let mut out = Vec::new();
    let arg_count = body.arg_count as u32;
    for local in body.local_decls.indices() {
        let local_u32 = local.as_u32();
        if local_u32 >= 1 && local_u32 <= arg_count {
            // Parameters are declared in the signature.
            continue;
        }
        let Some(name) = resolver.label_local(local) else {
            continue;
        };
        let ty = lower_ty(tcx, body.local_decls[local].ty);
        out.push(Stmt::Let { pat: name, ty: Some(ty), init: None });
    }
    out
}

// Post-structural return materialization hook.
// Structural pipeline already guarantees deterministic __ret synthesis
// via stage_finalize_body_with_ret_fallback. This hook exists so
// engine.rs can invoke it without introducing suppressed bindings.
pub(crate) fn materialize_return_local(_body: &mut Body) {
    // No-op: structural fallback already guarantees a concrete __ret binding.
}

// Post-structural gap resolution hook.
// Structural pipeline already injects a deterministic __ret assignment
// when missing. This function intentionally performs no additional
// mutation to avoid duplicating return synthesis logic.
pub(crate) fn resolve_ret_gaps_with(_body: &mut Body, _default_expr: &str) {
    let _ = (_body, _default_expr);
}

use rustc_middle::mir;
use rustc_middle::ty::{self, TyCtxt};

use crate::capture::helpers::{lower_ty, render_type_expr};
use crate::capture::mir::filters;
use crate::capture::mir::resolver::LocalNameResolver;
use crate::norm;
use crate::types::Stmt;

pub(crate) enum ArgLabel {
    Value(String),
    Omit,
}

pub(crate) fn mir_operand_label_for_arg<'tcx>(tcx: TyCtxt<'tcx>, operand: &mir::Operand<'tcx>, resolver: &LocalNameResolver, local_decls: Option<&mir::LocalDecls<'tcx>>) -> Option<ArgLabel> {
    if let mir::Operand::Constant(c) = operand {
        if let Some(expr) = closure_expr_from_const(tcx, c) {
            return Some(ArgLabel::Value(expr));
        }
    }
    match operand {
        mir::Operand::Constant(c) if constant_is_implicit_zst_value(c) => Some(ArgLabel::Omit),
        _ => mir_operand_label_with_decls(tcx, operand, resolver, local_decls).map(ArgLabel::Value),
    }
}

fn constant_is_implicit_zst_value(constant: &mir::ConstOperand<'_>) -> bool {
    matches!(constant.const_.ty().kind(), ty::TyKind::Closure(..) | ty::TyKind::Coroutine(..) | ty::TyKind::CoroutineClosure(..))
}

pub(crate) fn mir_operand_label<'tcx>(tcx: TyCtxt<'tcx>, operand: &mir::Operand<'tcx>, resolver: &LocalNameResolver) -> Option<String> {
    mir_operand_label_with_decls(tcx, operand, resolver, None)
}

pub(crate) fn mir_operand_label_with_decls<'tcx>(tcx: TyCtxt<'tcx>, operand: &mir::Operand<'tcx>, resolver: &LocalNameResolver, local_decls: Option<&mir::LocalDecls<'tcx>>) -> Option<String> {
    match operand {
        mir::Operand::Copy(place) | mir::Operand::Move(place) => {
            if let Some(label) = label_operand_place(place, resolver) {
                return Some(label);
            }
            if let Some(decls) = local_decls {
                let ty = decls[place.local].ty;
                if is_closure_or_fn_ptr(ty) {
                    return resolver.label_local(place.local);
                }
            }
            None
        }
        mir::Operand::Constant(c) => {
            if let Some(lit) = const_literal_expr(tcx, c) {
                return Some(lit);
            }
            if is_byte_string_ty(c.const_.ty()) {
                if let Ok(snippet) = tcx.sess.source_map().span_to_snippet(c.span)
                    && let Some(bs) = extract_byte_string_literal(&snippet)
                {
                    return Some(bs);
                }
                let raw = c.const_.to_string();
                if let Some(bs) = extract_byte_string_literal(&raw) {
                    return Some(bs);
                }
            }
            if let Some(expr) = closure_expr_from_const(tcx, c) {
                return Some(expr);
            }
            if let ty::TyKind::FnDef(did, _) = c.const_.ty().kind() {
                return Some(norm::path(tcx, *did));
            }
            if let mir::Const::Unevaluated(uneval, _) = c.const_ {
                Some(norm::path(tcx, uneval.def))
            } else {
                let const_str = c.const_.to_string();
                if const_str.is_empty() || const_str == "_" || filters::is_internal_mir_const_repr(&const_str) {
                    None
                } else {
                    Some(filters::strip_instance_generics(&const_str))
                }
            }
        }
        mir::Operand::RuntimeChecks(_) => None,
    }
}

fn label_operand_place(place: &mir::Place<'_>, resolver: &LocalNameResolver) -> Option<String> {
    if place.projection.is_empty() {
        return resolver.label_place(place);
    }
    // Operand-side projection rendering is intentionally strict because this path
    // lacks full type context and can otherwise leak MIR-only field accesses.
    if place.projection.len() == 1 && matches!(place.projection[0], mir::ProjectionElem::Deref) {
        return Some(format!("*{}", resolver.label_local(place.local)?));
    }
    None
}

pub(crate) fn mir_call_args_labels<'tcx>(
    tcx: TyCtxt<'tcx>, args: &[rustc_span::source_map::Spanned<mir::Operand<'tcx>>], resolver: &LocalNameResolver, local_decls: &mir::LocalDecls<'tcx>,
) -> Option<Vec<String>> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match mir_operand_label_for_arg(tcx, &arg.node, resolver, Some(local_decls))? {
            ArgLabel::Value(v) => out.push(v),
            ArgLabel::Omit => return None,
        }
    }
    Some(out)
}

pub(crate) fn filtered_internal_call_target<'tcx>(tcx: TyCtxt<'tcx>, func: &mir::Operand<'tcx>, resolver: &LocalNameResolver) -> bool {
    if let Some(path) = call_target_path(tcx, func)
        && filters::is_filtered_internal_call_path(&path)
    {
        return true;
    }
    mir_operand_label(tcx, func, resolver).map(|path| filters::is_filtered_internal_call_path(&path)).unwrap_or(false)
}

pub(crate) fn call_target_path<'tcx>(tcx: TyCtxt<'tcx>, func: &mir::Operand<'tcx>) -> Option<String> {
    let (did, _) = func.const_fn_def()?;
    Some(norm::path(tcx, did))
}

pub(crate) fn is_format_call_target<'tcx>(tcx: TyCtxt<'tcx>, func: &mir::Operand<'tcx>) -> bool {
    let Some(path) = call_target_path(tcx, func) else {
        return false;
    };
    matches!(path.as_str(), "std::fmt::format" | "core::fmt::format" | "alloc::fmt::format") || (path.contains("fmt::") && path.ends_with("::format"))
}

pub(crate) fn is_deref_call_target<'tcx>(tcx: TyCtxt<'tcx>, func: &mir::Operand<'tcx>, resolver: &LocalNameResolver) -> bool {
    let by_path = call_target_path(tcx, func).map(|p| p.contains("ops::deref::Deref::deref")).unwrap_or(false);
    if by_path {
        return true;
    }
    mir_operand_label(tcx, func, resolver).map(|f| f.ends_with("::deref")).unwrap_or(false)
}

pub(crate) fn mir_method_call_stmt<'tcx>(
    tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, func: &mir::Operand<'tcx>, args: &[rustc_span::source_map::Spanned<mir::Operand<'tcx>>], resolver: &LocalNameResolver, dest: String,
) -> Option<Stmt> {
    if args.is_empty() {
        return None;
    }
    if let Some((did, _)) = func.const_fn_def() {
        if !matches!(tcx.def_kind(did), rustc_hir::def::DefKind::AssocFn) {
            return None;
        }
        let assoc = tcx.associated_item(did);
        let has_self_param = matches!(assoc.kind, ty::AssocKind::Fn { has_self: true, .. });
        if !has_self_param {
            return None;
        }
        let receiver = match mir_operand_label_for_arg(tcx, &args[0].node, resolver, Some(local_decls))? {
            ArgLabel::Value(v) => v,
            ArgLabel::Omit => return None,
        };
        let method = tcx.item_name(did).to_string();
        let args = mir_call_args_labels(tcx, &args[1..], resolver, local_decls)?;
        return Some(Stmt::MethodCall { receiver, method, args, dest: Some(dest) });
    }

    let func_label = mir_operand_label(tcx, func, resolver)?;
    let method = dynamic_trait_method_name(&func_label)?;
    let receiver = match mir_operand_label_for_arg(tcx, &args[0].node, resolver, Some(local_decls))? {
        ArgLabel::Value(v) => v,
        ArgLabel::Omit => return None,
    };
    let args = mir_call_args_labels(tcx, &args[1..], resolver, local_decls)?;
    Some(Stmt::MethodCall { receiver, method, args, dest: Some(dest) })
}

pub(crate) fn mir_call_stmt<'tcx>(
    tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, func: &mir::Operand<'tcx>, args: &[rustc_span::source_map::Spanned<mir::Operand<'tcx>>], resolver: &LocalNameResolver, dest: String,
) -> Option<Stmt> {
    let func = if let Some((did, _)) = func.const_fn_def() {
        if matches!(tcx.def_kind(did), rustc_hir::def::DefKind::AssocFn) {
            let assoc = tcx.associated_item(did);
            if matches!(assoc.container, ty::AssocContainer::InherentImpl | ty::AssocContainer::TraitImpl(_)) {
                let impl_did = assoc.container_id(tcx);
                let self_ty = tcx.type_of(impl_did).instantiate_identity();
                let self_path = render_type_expr(tcx, &lower_ty(tcx, self_ty));
                let method = tcx.item_name(did).to_string();
                format!("{self_path}::{method}")
            } else {
                filters::strip_instance_generics(&norm::path(tcx, did))
            }
        } else {
            filters::strip_instance_generics(&norm::path(tcx, did))
        }
    } else {
        filters::strip_instance_generics(&mir_operand_label(tcx, func, resolver)?)
    };
    if filters::path_has_unresolved_generic(&func) {
        return None;
    }
    let args = mir_call_args_labels(tcx, args, resolver, local_decls)?;
    Some(Stmt::Call { func, args, dest: Some(dest) })
}

fn dynamic_trait_method_name(func_label: &str) -> Option<String> {
    if !func_label.contains(" as ") {
        return None;
    }
    let method = func_label.rsplit("::").next()?;
    if method.is_empty() || !method.chars().all(|c| c == '_' || c.is_ascii_alphanumeric()) {
        return None;
    }
    Some(method.to_string())
}

fn is_closure_or_fn_ptr(ty: ty::Ty<'_>) -> bool {
    matches!(ty.kind(), ty::TyKind::Closure(..) | ty::TyKind::Coroutine(..) | ty::TyKind::CoroutineClosure(..) | ty::TyKind::FnPtr(..) | ty::TyKind::FnDef(..))
}

fn closure_expr_from_const<'tcx>(tcx: TyCtxt<'tcx>, constant: &mir::ConstOperand<'tcx>) -> Option<String> {
    match constant.const_.ty().kind() {
        ty::TyKind::Closure(def_id, ..) => closure_expr_from_def_id(tcx, *def_id),
        ty::TyKind::Coroutine(def_id, ..) => closure_expr_from_def_id(tcx, *def_id),
        ty::TyKind::CoroutineClosure(def_id, ..) => closure_expr_from_def_id(tcx, *def_id),
        _ => None,
    }
}

fn const_literal_expr<'tcx>(tcx: TyCtxt<'tcx>, constant: &mir::ConstOperand<'tcx>) -> Option<String> {
    let (inner_ty, ref_depth) = peel_ref_layers(constant.const_.ty());
    let mut lit = const_span_literal(tcx, constant)
        .or_else(|| unevaluated_anon_const_literal(tcx, constant))?;

    let builtin_refs = builtin_ref_layers(&lit, inner_ty);
    if ref_depth > builtin_refs {
        let extra = "&".repeat(ref_depth - builtin_refs);
        lit = format!("{extra}{lit}");
    }
    Some(lit)
}

fn peel_ref_layers<'tcx>(mut ty: ty::Ty<'tcx>) -> (ty::Ty<'tcx>, usize) {
    let mut depth = 0usize;
    while let ty::TyKind::Ref(_, inner, _) = ty.kind() {
        depth += 1;
        ty = *inner;
    }
    (ty, depth)
}

fn const_span_literal(tcx: TyCtxt<'_>, constant: &mir::ConstOperand<'_>) -> Option<String> {
    let snippet = tcx.sess.source_map().span_to_snippet(constant.span).ok()?;
    let trimmed = snippet.trim();
    if is_string_like_literal(trimmed) {
        return Some(trimmed.to_string());
    }
    None
}

fn unevaluated_anon_const_literal<'tcx>(tcx: TyCtxt<'tcx>, constant: &mir::ConstOperand<'tcx>) -> Option<String> {
    let mir::Const::Unevaluated(uneval, _) = constant.const_ else {
        return None;
    };
    let local = uneval.def.as_local()?;
    let rustc_hir::Node::AnonConst(anon) = tcx.hir_node_by_def_id(local) else {
        return None;
    };
    let body = tcx.hir_body(anon.body);
    let snippet = tcx.sess.source_map().span_to_snippet(body.value.span).ok()?;
    let trimmed = snippet.trim();
    if is_string_like_literal(trimmed) {
        Some(trimmed.to_string())
    } else {
        None
    }
}

fn is_string_like_literal(s: &str) -> bool {
    let t = s.trim_start_matches('&').trim();
    t.starts_with('"') || t.starts_with("r\"") || t.starts_with("b\"") || t.starts_with("br\"")
}

fn extract_byte_string_literal(raw: &str) -> Option<String> {
    let s = raw.trim();
    if s.is_empty() {
        return None;
    }
    if s.starts_with("b\"") || s.starts_with("br\"") || s.starts_with("&b\"") || s.starts_with("&br\"") {
        return Some(s.to_string());
    }
    if let Some(i) = s.find("b\"") {
        return Some(s[i..].to_string());
    }
    if let Some(i) = s.find("br\"") {
        return Some(s[i..].to_string());
    }
    None
}

fn builtin_ref_layers(inner_lit: &str, inner_ty: ty::Ty<'_>) -> usize {
    let trimmed = inner_lit.trim();
    if trimmed.starts_with('&') {
        return 1;
    }
    match inner_ty.kind() {
        ty::TyKind::Str => 1,
        ty::TyKind::Slice(elem) if matches!(elem.kind(), ty::TyKind::Uint(ty::UintTy::U8)) => 1,
        _ => 0,
    }
}

fn is_byte_string_ty(mut ty: ty::Ty<'_>) -> bool {
    while let ty::TyKind::Ref(_, inner, _) = ty.kind() {
        ty = *inner;
    }
    match ty.kind() {
        ty::TyKind::Array(elem, _) | ty::TyKind::Slice(elem) => {
            matches!(elem.kind(), ty::TyKind::Uint(ty::UintTy::U8))
        }
        _ => false,
    }
}

pub(crate) fn closure_placeholder_expr_from_aggregate<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: rustc_span::def_id::DefId,
    _args: ty::GenericArgsRef<'tcx>,
) -> Option<String> {
    closure_expr_from_def_id(tcx, def_id)
}

fn closure_expr_from_def_id(tcx: TyCtxt<'_>, def_id: rustc_span::def_id::DefId) -> Option<String> {
    // Structural source extraction from rustc metadata/HIR; no text heuristics.
    let snippet = if let Some(local_def_id) = def_id.as_local() {
        match tcx.hir_node_by_def_id(local_def_id) {
            rustc_hir::Node::Expr(expr) => tcx.sess.source_map().span_to_snippet(expr.span).ok(),
            rustc_hir::Node::Item(item) => tcx.sess.source_map().span_to_snippet(item.span).ok(),
            _ => tcx.sess.source_map().span_to_snippet(tcx.def_span(def_id)).ok(),
        }
    } else {
        tcx.sess.source_map().span_to_snippet(tcx.def_span(def_id)).ok()
    }?;
    let trimmed = snippet.trim();
    if trimmed.is_empty() {
        None
    } else {
        Some(trimmed.to_string())
    }
}

fn closure_placeholder_expr_from_sig<'tcx>(tcx: TyCtxt<'tcx>, sig: ty::Binder<'tcx, ty::FnSig<'tcx>>) -> Option<String> {
    let inputs = sig.inputs().skip_binder();
    let output = sig.output().skip_binder();
    let arg_tys = inputs
        .iter()
        .map(|ty| render_type_expr(tcx, &lower_ty(tcx, *ty)))
        .collect::<Vec<_>>();
    let ret_ty = render_type_expr(tcx, &lower_ty(tcx, output));
    panic!(
        "canon-capture invariant violation: unresolved closure lowering args={:?} ret={}",
        arg_tys,
        ret_ty
    );
}

use std::collections::HashSet;

use crate::capture::mir::analysis::SwitchAnalysis;
use crate::capture::mir::util as mir_util;
use crate::types::{BasicBlock, Stmt, Terminator};

#[derive(Clone, Copy, PartialEq, Eq)]
pub(crate) enum BlockRole {
    SwitchSource,
    SwitchArm,
    Normal,
}

pub(crate) struct EmittedBlock {
    pub(crate) role: BlockRole,
    pub(crate) block: BasicBlock,
}

pub(crate) struct BodyDraft {
    pub(crate) emitted_blocks: Vec<EmittedBlock>,
    pub(crate) suppressed_dest_sentinels: Vec<Stmt>,
}

pub(crate) type ProloguePass = fn(Vec<EmittedBlock>, Vec<Stmt>) -> Vec<EmittedBlock>;
pub(crate) type NormalizePass = fn(Vec<EmittedBlock>) -> Vec<EmittedBlock>;
pub(crate) type FinalizePass = fn(Vec<EmittedBlock>) -> Vec<BasicBlock>;

pub(crate) struct NormalizationPipeline {
    prologue: ProloguePass,
    normalize: NormalizePass,
    finalize: FinalizePass,
}

impl NormalizationPipeline {
    pub(crate) fn canonical() -> Self {
        Self { prologue: pass_inject_suppressed_prologue, normalize: pass_lower_match_and_prune_bindings, finalize: pass_strip_roles }
    }

    pub(crate) fn run(&self, draft: BodyDraft) -> Vec<BasicBlock> {
        let emitted = (self.prologue)(draft.emitted_blocks, draft.suppressed_dest_sentinels);
        let emitted = (self.normalize)(emitted);
        (self.finalize)(emitted)
    }
}

pub(crate) fn make_body_draft(emitted_blocks: Vec<EmittedBlock>, suppressed_dest_sentinels: Vec<Stmt>) -> BodyDraft {
    BodyDraft { emitted_blocks, suppressed_dest_sentinels }
}

pub(crate) fn emit_special_block(returns_unit: bool, mir_idx_usize: usize, blocks: &[EmittedBlock], switch_analysis: &SwitchAnalysis, defined: &mut HashSet<String>) -> Option<EmittedBlock> {
    if switch_analysis.switch_sources.contains(&mir_idx_usize) {
        if switch_analysis.iterator_switches.contains_key(&mir_idx_usize) {
            return None;
        }
        let _ = (returns_unit, blocks, defined);
        return Some(EmittedBlock { role: BlockRole::SwitchSource, block: BasicBlock { stmts: Vec::new(), terminator: Terminator::Unreachable } });
    }
    if switch_analysis.switchint_arm_blocks.contains(&mir_idx_usize) {
        // Do not drop switch arm bodies. Switch arm blocks frequently
        // contain the only structural assignments that bind locals
        // (e.g., iterator `child` bindings). Emitting empty arm blocks
        // causes undefined local errors in emitted Rust.
        return None;
    }
    None
}

pub(crate) fn normalize_blocks(emitted: Vec<EmittedBlock>, suppressed_dest_sentinels: Vec<Stmt>) -> Vec<BasicBlock> {
    normalize_draft(make_body_draft(emitted, suppressed_dest_sentinels))
}

pub(crate) fn normalize_draft(draft: BodyDraft) -> Vec<BasicBlock> {
    NormalizationPipeline::canonical().run(draft)
}

pub(crate) fn make_normal_block(stmts: Vec<Stmt>, term: Terminator) -> EmittedBlock {
    EmittedBlock { role: BlockRole::Normal, block: BasicBlock { stmts, terminator: term } }
}

pub(crate) fn blocks_have_ret_match(blocks: &[EmittedBlock]) -> bool {
    blocks.iter().any(|bb| bb.block.stmts.iter().any(|stmt| matches!(stmt, Stmt::Match { dest: Some(dest) } if dest == "__ret")))
}

pub(crate) fn blocks_have_ret_binding(blocks: &[EmittedBlock]) -> bool {
    blocks.iter().any(|bb| bb.block.stmts.iter().any(mir_util::stmt_defines_ret))
}

fn pass_inject_suppressed_prologue(mut emitted: Vec<EmittedBlock>, suppressed_dest_sentinels: Vec<Stmt>) -> Vec<EmittedBlock> {
    if suppressed_dest_sentinels.is_empty() {
        return emitted;
    }
    if let Some(first_normal_idx) = emitted.iter().position(|b| b.role == BlockRole::Normal) {
        let mut merged = suppressed_dest_sentinels;
        merged.append(&mut emitted[first_normal_idx].block.stmts);
        emitted[first_normal_idx].block.stmts = merged;
    }
    emitted
}

fn pass_strip_roles(emitted: Vec<EmittedBlock>) -> Vec<BasicBlock> {
    emitted.into_iter().map(|e| e.block).collect()
}

fn pass_lower_match_and_prune_bindings(emitted: Vec<EmittedBlock>) -> Vec<EmittedBlock> {
    let emitted = pass_lower_match_dest_to_suppressed(emitted);
    pass_prune_unused_suppressed_bindings(emitted)
}

fn pass_lower_match_dest_to_suppressed(mut emitted: Vec<EmittedBlock>) -> Vec<EmittedBlock> {
    for block in &mut emitted {
        for stmt in &mut block.block.stmts {
            if let Stmt::Match { dest: Some(dest) } = stmt {
                // Structural invariant: do not introduce suppressed bindings.
                // Instead, lower non-__ret match destinations to a concrete
                // default value so no suppressed placeholder is emitted.
                if dest != "__ret" {
                    // Avoid emitting untyped Default::default() for match
                    // destinations, as this causes downstream type
                    // inference failures. Use unit placeholder; structural
                    // return synthesis handles typed defaults where needed.
                    *stmt = Stmt::Assign { lhs: dest.clone(), rhs: "panic!(\"canon unlowered match dest\")".to_string() };
                }
            }
        }
    }
    emitted
}

fn pass_prune_unused_suppressed_bindings(emitted: Vec<EmittedBlock>) -> Vec<EmittedBlock> {
    // Suppressed bindings are no longer introduced anywhere in the
    // structural pipeline. Pruning logic that reasons about the
    // "__canon_suppressed__" sentinel can cause accidental removal
    // of required assignments if stale sentinels appear. Make this
    // pass a no-op to preserve all structurally lowered bindings.
    emitted
}

fn collect_used_value_names(blocks: &[EmittedBlock]) -> HashSet<String> {
    let mut used = HashSet::new();
    for block in blocks {
        for stmt in &block.block.stmts {
            record_stmt_uses(stmt, &mut used);
        }
        record_terminator_uses(&block.block.terminator, &mut used);
    }
    used
}

fn record_stmt_uses(stmt: &Stmt, used: &mut HashSet<String>) {
    match stmt {
        Stmt::Assign { rhs, .. } => extend_expr_tokens(rhs, used),
        Stmt::Expr(expr) => extend_expr_tokens(expr, used),
        Stmt::Call { args, .. } => {
            for arg in args {
                extend_expr_tokens(arg, used);
            }
        }
        Stmt::FieldAccess { base, .. } => extend_expr_tokens(base, used),
        Stmt::MethodCall { receiver, args, .. } => {
            extend_expr_tokens(receiver, used);
            for arg in args {
                extend_expr_tokens(arg, used);
            }
        }
        Stmt::StructLit { fields, .. } => {
            for (_, value) in fields {
                extend_expr_tokens(value, used);
            }
        }
        Stmt::Return(Some(value)) => extend_expr_tokens(value, used),
        Stmt::Let { init: Some(init), .. } => extend_expr_tokens(init, used),
        _ => {}
    }
}

fn record_terminator_uses(term: &Terminator, used: &mut HashSet<String>) {
    if let Terminator::Branch { cond, .. } = term {
        extend_expr_tokens(cond, used);
    }
}

fn extend_expr_tokens(expr: &str, out: &mut HashSet<String>) {
    let stripped = strip_quoted_literals(expr);
    for tok in stripped.split(|c: char| !(c == '_' || c.is_ascii_alphanumeric())) {
        if tok.is_empty() {
            continue;
        }
        if tok.chars().next().is_some_and(|c| c.is_ascii_digit()) {
            continue;
        }
        out.insert(tok.to_string());
    }
}

fn strip_quoted_literals(expr: &str) -> String {
    let mut out = String::with_capacity(expr.len());
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    for ch in expr.chars() {
        if escaped {
            escaped = false;
            continue;
        }
        if (in_single || in_double) && ch == '\\' {
            escaped = true;
            continue;
        }
        if in_single {
            if ch == '\'' {
                in_single = false;
            }
            continue;
        }
        if in_double {
            if ch == '"' {
                in_double = false;
            }
            continue;
        }
        if ch == '\'' {
            in_single = true;
            continue;
        }
        if ch == '"' {
            in_double = true;
            continue;
        }
        out.push(ch);
    }
    out
}

use rustc_middle::mir;
use rustc_middle::ty::TyCtxt;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum MirOpKind {
    FieldAccess,
    StructLit,
    OpaqueAggregate,
    ZeroArgEnumCtor,
    ArrayAggregate,
    ConstUse,
    Assign,
}

pub struct MirPattern {
    pub kind: MirOpKind,
    pub predicate: for<'tcx> fn(TyCtxt<'tcx>, &mir::Rvalue<'tcx>) -> bool,
}

fn is_field_access_pattern(_tcx: TyCtxt<'_>, rvalue: &mir::Rvalue<'_>) -> bool {
    matches!(
        rvalue,
        mir::Rvalue::Use(mir::Operand::Copy(place) | mir::Operand::Move(place))
            if matches!(place.as_ref().last_projection(), Some((_, mir::ProjectionElem::Field(..))))
    )
}

fn is_struct_lit_pattern(_tcx: TyCtxt<'_>, rvalue: &mir::Rvalue<'_>) -> bool {
    matches!(rvalue, mir::Rvalue::Aggregate(kind, _) if matches!(&**kind, mir::AggregateKind::Adt(_, _, _, _, _)))
}

fn is_opaque_aggregate_pattern(_tcx: TyCtxt<'_>, rvalue: &mir::Rvalue<'_>) -> bool {
    matches!(
        rvalue,
        mir::Rvalue::Aggregate(kind, _)
            if matches!(
                &**kind,
                mir::AggregateKind::Closure(_, _)
                    | mir::AggregateKind::Coroutine(_, _)
                    | mir::AggregateKind::CoroutineClosure(_, _)
            )
    )
}

fn is_zero_arg_enum_ctor_pattern(tcx: TyCtxt<'_>, rvalue: &mir::Rvalue<'_>) -> bool {
    let mir::Rvalue::Use(mir::Operand::Constant(c)) = rvalue else {
        return false;
    };
    if let rustc_middle::ty::TyKind::FnDef(did, _) = c.const_.ty().kind() {
        if matches!(tcx.def_kind(*did), rustc_hir::def::DefKind::Ctor(rustc_hir::def::CtorOf::Variant, rustc_hir::def::CtorKind::Const)) {
            return true;
        }
    }
    let rustc_middle::ty::TyKind::Adt(adt, _) = c.const_.ty().kind() else {
        return false;
    };
    if !adt.is_enum() {
        return false;
    }
    if let mir::Const::Val(v, ty) = c.const_ {
        if v.try_to_scalar_int().is_some() && matches!(ty.kind(), rustc_middle::ty::TyKind::Adt(adt2, _) if adt2.is_enum()) && adt.variants().iter().any(|var| var.fields.is_empty()) {
            return true;
        }
    }
    false
}

fn is_array_aggregate_pattern(_tcx: TyCtxt<'_>, rvalue: &mir::Rvalue<'_>) -> bool {
    matches!(rvalue, mir::Rvalue::Aggregate(kind, _) if matches!(&**kind, mir::AggregateKind::Array(_)))
}

static MIR_PATTERNS: &[MirPattern] = &[
    MirPattern { kind: MirOpKind::FieldAccess, predicate: is_field_access_pattern },
    MirPattern { kind: MirOpKind::StructLit, predicate: is_struct_lit_pattern },
    MirPattern { kind: MirOpKind::OpaqueAggregate, predicate: is_opaque_aggregate_pattern },
    MirPattern { kind: MirOpKind::ZeroArgEnumCtor, predicate: is_zero_arg_enum_ctor_pattern },
    MirPattern { kind: MirOpKind::ArrayAggregate, predicate: is_array_aggregate_pattern },
    MirPattern { kind: MirOpKind::ConstUse, predicate: |_tcx, rvalue| matches!(rvalue, mir::Rvalue::Use(mir::Operand::Constant(_))) },
];

pub fn dispatch_stmt_pattern<'tcx>(tcx: TyCtxt<'tcx>, rvalue: &mir::Rvalue<'tcx>) -> MirOpKind {
    for pattern in MIR_PATTERNS {
        if (pattern.predicate)(tcx, rvalue) {
            return pattern.kind;
        }
    }
    MirOpKind::Assign
}

use rustc_middle::mir;
use std::collections::HashMap;

pub(crate) struct LocalNameResolver {
    by_local: HashMap<u32, String>,
}

impl LocalNameResolver {
    pub(crate) fn new<'tcx>(body: &mir::Body<'tcx>, param_names: &[String]) -> Self {
        let mut by_local: HashMap<u32, String> = HashMap::new();
        let mut owner_by_name: HashMap<String, u32> = HashMap::new();
        insert_unique_name(&mut by_local, &mut owner_by_name, 0, "__ret".to_string());
        for (idx, name) in param_names.iter().enumerate() {
            let local_idx = (idx + 1) as u32;
            if is_rust_ident(name) {
                insert_unique_name(&mut by_local, &mut owner_by_name, local_idx, name.clone());
            }
        }
        for dbg in &body.var_debug_info {
            let mir::VarDebugInfoContents::Place(place) = &dbg.value else {
                continue;
            };
            let projection_ok = place.projection.is_empty() || (place.projection.len() == 1 && matches!(place.projection[0], mir::ProjectionElem::Field(..) | mir::ProjectionElem::Deref));
            if !projection_ok {
                continue;
            }
            let name = dbg.name.as_str().to_string();
            if !is_rust_ident(&name) {
                continue;
            }
            if by_local.contains_key(&place.local.as_u32()) {
                continue;
            }
            insert_unique_name(&mut by_local, &mut owner_by_name, place.local.as_u32(), name);
        }
        for local in body.local_decls.indices() {
            if by_local.contains_key(&local.as_u32()) {
                continue;
            }
            insert_unique_name(&mut by_local, &mut owner_by_name, local.as_u32(), format!("_v{}", local.as_u32()));
        }
        Self { by_local }
    }

    pub(crate) fn label_place(&self, place: &mir::Place<'_>) -> Option<String> {
        if place.projection.iter().any(|p| matches!(p, mir::ProjectionElem::Downcast(..))) {
            return None;
        }
        if place.projection.iter().any(|p| matches!(p, mir::ProjectionElem::OpaqueCast(..) | mir::ProjectionElem::UnwrapUnsafeBinder(..))) {
            return None;
        }
        if !place.projection.is_empty() {
            return None;
        }
        self.label_local(place.local)
    }

    pub(crate) fn label_local(&self, local: mir::Local) -> Option<String> {
        let name = self.by_local.get(&local.as_u32())?;
        if !is_value_name_safe(name) {
            return None;
        }
        Some(name.clone())
    }

    pub(crate) fn label_place_ref(&self, place: mir::PlaceRef<'_>) -> Option<String> {
        if place.projection.iter().any(|p| matches!(p, mir::ProjectionElem::Downcast(..))) {
            return None;
        }
        if place.projection.iter().any(|p| matches!(p, mir::ProjectionElem::OpaqueCast(..) | mir::ProjectionElem::UnwrapUnsafeBinder(..))) {
            return None;
        }
        if !place.projection.is_empty() {
            return None;
        }
        let name = self.by_local.get(&place.local.as_u32())?;
        if !is_value_name_safe(name) {
            return None;
        }
        Some(name.clone())
    }
}

fn is_rust_ident(s: &str) -> bool {
    let mut chars = s.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    if !(first == '_' || first.is_ascii_alphabetic()) {
        return false;
    }
    chars.all(|c| c == '_' || c.is_ascii_alphanumeric())
}

fn is_value_name_safe(s: &str) -> bool {
    if s.chars().next().is_some_and(|c| c.is_ascii_uppercase()) {
        return false;
    }
    true
}

fn insert_unique_name(by_local: &mut HashMap<u32, String>, owner_by_name: &mut HashMap<String, u32>, local_idx: u32, preferred: String) {
    if let Some(existing) = owner_by_name.get(&preferred) {
        if *existing == local_idx {
            by_local.insert(local_idx, preferred);
            return;
        }
        let mut candidate = format!("{preferred}_{local_idx}");
        while owner_by_name.contains_key(&candidate) {
            candidate.push('_');
        }
        owner_by_name.insert(candidate.clone(), local_idx);
        by_local.insert(local_idx, candidate);
        return;
    }
    owner_by_name.insert(preferred.clone(), local_idx);
    by_local.insert(local_idx, preferred);
}

use crate::types::{Body, Stmt, Terminator};

/// Deterministically bind `__ret` to the MIR return place for
/// non-unit functions when structural lowering produced no
/// explicit return expression.
pub fn ensure_ret_bound(body: &mut Body, returns_unit: bool) {
    if returns_unit {
        return;
    }

    // Ensure there is an explicit structural return of `__ret`
    // so the return place is materialized in CanonIR.
    if let Body::Blocks(blocks) = body {
        if let Some(last_bb) = blocks.last_mut() {
            // Normalize reference layers at the Rust return boundary.
            // If `__ret` was inferred as `&T` but the Rust signature
            // expects `T`, dereference once here to preserve return
            // type consistency.
            // Do not synthesize a dereference at the return boundary.
            // The return place must already have the authoritative
            // function signature type.
            last_bb.stmts.push(Stmt::Return(Some("__ret".to_string())));
            last_bb.terminator = Terminator::Return;
        }
    }
}

use rustc_middle::mir;
use rustc_middle::ty::TyCtxt;
use std::collections::HashSet;
// structural fallback adjustments applied

use crate::capture::mir::analysis::SwitchAnalysis;
use crate::capture::mir::guard as mir_guard;
use crate::capture::mir::ops as mir_ops;
use crate::capture::mir::resolver::LocalNameResolver;
use crate::capture::mir::util as mir_util;
use crate::types::{Stmt, Terminator};

#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_call_terminator<'tcx>(
    tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, func: &mir::Operand<'tcx>, args: &[rustc_span::source_map::Spanned<mir::Operand<'tcx>>], destination: &mir::Place<'tcx>,
    target: Option<mir::BasicBlock>, resolver: &LocalNameResolver, mir_to_emitted: &[Option<u32>], stmts: &mut Vec<Stmt>, defined: &mut HashSet<String>,
    suppressed_sentinel_names: &mut HashSet<String>, has_match_dest: bool,
) -> Terminator {
    let must_use_call =
        mir_ops::call_target_path(tcx, func).map(|p| p.contains("must_use")).unwrap_or(false) || mir_ops::mir_operand_label(tcx, func, resolver).map(|f| f.ends_with("must_use")).unwrap_or(false);

    if mir_ops::is_deref_call_target(tcx, func, resolver)
        && let Some(dest) = mir_util::label_place_dest(resolver, destination)
    {
        if let Some(arg) = args.first()
            && let Some(arg_value) = mir_ops::mir_operand_label(tcx, &arg.node, resolver)
        {
            stmts.push(Stmt::Assign { lhs: dest.clone(), rhs: arg_value });
            defined.insert(dest);
        } else {
            panic!("canon-capture invariant violation: unsupported deref call lowering");
        }
    } else if must_use_call && let Some(dest) = mir_util::label_place_dest(resolver, destination) {
        if let Some(arg) = args.first()
            && let Some(arg_value) = mir_ops::mir_operand_label(tcx, &arg.node, resolver)
        {
            stmts.push(Stmt::Assign { lhs: dest.clone(), rhs: arg_value });
            defined.insert(dest);
        } else {
            panic!("canon-capture invariant violation: unsupported must_use call lowering");
        }
    } else if let Some(dest) = mir_util::label_place_dest(resolver, destination)
        && let Some(method_stmt) = mir_ops::mir_method_call_stmt(tcx, local_decls, func, args, resolver, dest.clone())
    {
        if let Stmt::MethodCall { dest: Some(dest), .. } = &method_stmt {
            defined.insert(dest.clone());
        }
        stmts.push(method_stmt);
    } else if let Some(dest) = mir_util::label_place_dest(resolver, destination)
        && let Some(call_stmt) = mir_ops::mir_call_stmt(tcx, local_decls, func, args, resolver, dest.clone())
    {
        if let Stmt::Call { dest: Some(dest), .. } = &call_stmt {
            defined.insert(dest.clone());
        }
        stmts.push(call_stmt);
    } else if let Some(dest) = mir_util::label_place_dest(resolver, destination) {
        // Structural fallback: emit a direct call expression assignment if possible.
        if let Some(func_label) = mir_ops::mir_operand_label(tcx, func, resolver)
            && let Some(arg_labels) = mir_call_args_labels_fallback(tcx, local_decls, args, resolver)
        {
            let call_expr = format!("{}({})", func_label, arg_labels.join(", "));
            stmts.push(Stmt::Assign { lhs: dest.clone(), rhs: call_expr });
            defined.insert(dest);
        } else {
            // Last-resort structural fallback: use a type-directed diverging panic
            // so the destination retains authoritative MIR type.
            let local = destination.local;
            let ty = local_decls[local].ty;
            let lowered = crate::capture::helpers::lower_ty(tcx, ty);
            let ty_expr = crate::capture::helpers::render_type_expr(tcx, &lowered);

            // Fail fast on private fmt internals instead of emitting casts
            // that reference unstable core internals. Do not attempt to
            // fabricate a typed fallback for these compiler-private types.
            if ty_expr.contains("fmt::rt::Argument") {
                panic!("canon invariant violation: unsupported call lowering for private fmt internal type `{}`", ty_expr);
            }

            panic!("canon-capture invariant violation: unresolved call lowering func={func:?} args={args:?} destination={destination:?}");
        }
    }

    target.and_then(|bb| mir_util::remap_bb_target(bb, mir_to_emitted)).map(Terminator::Goto).unwrap_or_else(|| {
        // Do not implicitly fabricate a suppressed __ret here.
        // __ret must be defined by structurally valid lowering paths
        // or by explicit suppressed-ret emission in return handling.
        Terminator::None
    })
}

#[allow(clippy::too_many_arguments)]
pub(crate) fn lower_non_call_terminator<'tcx>(
    tcx: TyCtxt<'tcx>, term_ref: &mir::Terminator<'tcx>, returns_unit: bool, resolver: &LocalNameResolver, mir_to_emitted: &[Option<u32>], stmts: &mut Vec<Stmt>, defined: &mut HashSet<String>,
    has_ret_binding: bool, has_match_dest: bool, mir_idx: usize, switch_analysis: &SwitchAnalysis,
) -> Terminator {
    match &term_ref.kind {
        mir::TerminatorKind::Return => {
            // Do NOT fabricate __ret here.
            // Deterministic structural fallback will synthesize return if needed.
            lower_return_terminator(returns_unit, stmts, defined, has_ret_binding, has_match_dest);
            Terminator::None
        }
        mir::TerminatorKind::Goto { target } | mir::TerminatorKind::Drop { target, .. } | mir::TerminatorKind::Assert { target, .. } => remap_to_goto(*target, mir_to_emitted),
        mir::TerminatorKind::SwitchInt { discr, .. } => {
            if let Some(body_entry) = switch_analysis.iterator_switches.get(&mir_idx).copied() {
                let target = mir::BasicBlock::from_usize(body_entry);
                return remap_to_goto(target, mir_to_emitted);
            }
            let mut succ = term_ref.successors();
            if let (Some(t), Some(f)) = (succ.next(), succ.next())
                && let Some(cond) = mir_ops::mir_operand_label(tcx, discr, resolver)
            {
                let true_bb = mir_util::remap_bb_target(t, mir_to_emitted);
                let false_bb = mir_util::remap_bb_target(f, mir_to_emitted);
                return match (true_bb, false_bb) {
                    (Some(t), Some(f)) => Terminator::Branch { cond, true_bb: t, false_bb: f },
                    (Some(t), None) => Terminator::Goto(t),
                    (None, Some(f)) => Terminator::Goto(f),
                    (None, None) => Terminator::None,
                };
            }
            Terminator::None
        }
        _ => Terminator::None,
    }
}

fn mir_call_args_labels_fallback<'tcx>(
    tcx: TyCtxt<'tcx>, local_decls: &mir::LocalDecls<'tcx>, args: &[rustc_span::source_map::Spanned<mir::Operand<'tcx>>], resolver: &LocalNameResolver,
) -> Option<Vec<String>> {
    if let Some(labels) = mir_ops::mir_call_args_labels(tcx, args, resolver, local_decls) {
        return Some(labels);
    }

    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match &arg.node {
            mir::Operand::Copy(place) | mir::Operand::Move(place) => {
                if let Some(label) = mir_ops::mir_operand_label_with_decls(tcx, &arg.node, resolver, Some(local_decls)) {
                    out.push(label);
                    continue;
                }
                if let Some(name) = resolver.label_local(place.local) {
                    out.push(name);
                    continue;
                }
                return None;
            }
            _ => {
                let label = mir_ops::mir_operand_label_with_decls(tcx, &arg.node, resolver, Some(local_decls))?;
                out.push(label);
            }
        }
    }
    Some(out)
}

fn remap_to_goto(target: mir::BasicBlock, mir_to_emitted: &[Option<u32>]) -> Terminator {
    mir_util::remap_bb_target(target, mir_to_emitted).map(Terminator::Goto).unwrap_or(Terminator::None)
}

fn lower_return_terminator(returns_unit: bool, stmts: &mut Vec<Stmt>, defined: &mut HashSet<String>, _has_ret_binding: bool, _has_match_dest: bool) {
    if returns_unit {
        stmts.push(Stmt::Return(None));
    } else {
        // RETURN INTEGRITY:
        // The MIR return place (local 0) must be lowered as a concrete
        // assignment to "__ret" before any Return terminator is emitted.
        // If it was not, this is a structural lowering defect and must
        // fail fast rather than fabricating a value or emitting an
        // untyped return that breaks downstream type determinism.
        if !defined.contains("__ret") {
            panic!("canon-capture invariant violation: non-unit function returning without __ret binding");
        }
        // Emit a structural return of the authoritative __ret binding.
        // No fabrication or fallback value is permitted here.
        // Do not blindly dereference at the return boundary; type
        // normalization must be handled during assignment/rvalue lowering.
        stmts.push(Stmt::Return(Some("__ret".to_string())));
    }
}

use rustc_middle::mir;
use rustc_middle::mir::visit::Visitor;
use std::collections::{HashMap, HashSet};

use crate::capture::mir::guard as mir_guard;
use crate::capture::mir::resolver::LocalNameResolver;
use crate::types::Stmt;

pub(crate) fn label_place_dest(resolver: &LocalNameResolver, place: &mir::Place<'_>) -> Option<String> {
    if let Some(name) = resolver.label_place(place) {
        return Some(name);
    }
    let has_unsafe_proj = place.projection.iter().any(|p| matches!(p, mir::ProjectionElem::Downcast(..) | mir::ProjectionElem::OpaqueCast(..) | mir::ProjectionElem::UnwrapUnsafeBinder(..)));
    if has_unsafe_proj {
        return None;
    }
    resolver.label_local(place.local)
}

pub(crate) fn remap_bb_target(target: mir::BasicBlock, mir_to_emitted: &[Option<u32>]) -> Option<u32> {
    mir_to_emitted.get(target.as_usize()).and_then(|slot| *slot)
}

pub(crate) fn bb_writes_return_place(bb: &mir::BasicBlockData<'_>) -> bool {
    for stmt in &bb.statements {
        let mir::StatementKind::Assign(boxed) = &stmt.kind else {
            continue;
        };
        let (lhs, _) = &**boxed;
        if lhs.local.as_u32() == 0 {
            return true;
        }
    }
    let Some(term) = &bb.terminator else {
        return false;
    };
    if let mir::TerminatorKind::Call { destination, .. } = &term.kind {
        return destination.local.as_u32() == 0;
    }
    false
}

pub(crate) fn stmt_defines_ret(stmt: &Stmt) -> bool {
    match stmt {
        Stmt::Assign { lhs, .. } => lhs == "__ret",
        Stmt::Call { dest: Some(dest), .. } => dest == "__ret",
        Stmt::FieldAccess { dest: Some(dest), .. } => dest == "__ret",
        Stmt::MethodCall { dest: Some(dest), .. } => dest == "__ret",
        Stmt::StructLit { dest: Some(dest), .. } => dest == "__ret",
        Stmt::Match { dest: Some(dest) } => dest == "__ret",
        _ => false,
    }
}

pub(crate) fn emit_suppressed_ret_binding(stmts: &mut Vec<Stmt>, defined: &mut HashSet<String>) {
    // Structural invariant: never synthesize suppressed return bindings.
    // Deterministic return fallback in lowering must handle missing __ret.
}

pub(crate) fn emit_suppressed_for_name(name: &str, stmts: &mut Vec<Stmt>, defined: &mut HashSet<String>, suppressed_sentinel_names: &mut HashSet<String>) {
    // Never suppress __ret; return must be lowered structurally.
    if name == "__ret" {
        return;
    }
    // Suppressed bindings are eliminated at this stage.
    // Structural lowering and deterministic return fallback
    // are responsible for maintaining invariants.
}

pub(crate) fn count_local_uses<'tcx>(body: &mir::Body<'tcx>) -> HashMap<u32, usize> {
    struct Counter {
        counts: HashMap<u32, usize>,
    }
    impl<'tcx> Visitor<'tcx> for Counter {
        fn visit_local(&mut self, local: mir::Local, context: rustc_middle::mir::visit::PlaceContext, location: rustc_middle::mir::Location) {
            if context.is_use() {
                *self.counts.entry(local.as_u32()).or_insert(0) += 1;
            }
            self.super_local(local, context, location);
        }
    }
    let mut counter = Counter { counts: HashMap::new() };
    counter.visit_body(body);
    counter.counts
}

use anyhow::Result;
use canon::ir::CanonIR;
use rustc_hir::def::DefKind;
use rustc_middle::ty::TyCtxt;
use rustc_span::def_id::DefId;

use crate::capture::{body, engine, relations};
use crate::{canon_assemble, index, Partial};

fn project_def(tcx: TyCtxt<'_>, def_id: DefId, index: &crate::index::Index) -> Partial {
    let mut partial = Partial::default();

    if let Some((nodes, item_edges)) = engine::lower_def(tcx, def_id, index) {
        partial.nodes.extend(nodes);
        partial.edge_hints.extend(item_edges);
    }

    if !matches!(tcx.def_kind(def_id), DefKind::Use) {
        partial.edge_hints.extend(relations::project_relations(tcx, def_id, index));
    }

    let (body_nodes, body_edges) = body::project_body(tcx, def_id, index);
    partial.nodes.extend(body_nodes);
    partial.edge_hints.extend(body_edges);

    partial
}

pub fn capture(tcx: TyCtxt<'_>) -> Result<CanonIR> {
    let idx = index::build_index(tcx);

    let partials: Vec<Partial> = idx.def_ids.iter().map(|d| project_def(tcx, *d, &idx)).collect();

    let canon = canon_assemble::canon_assemble(tcx, &idx, partials);
    super::validate::structural::validate(&canon)?;
    Ok(canon)
}

use crate::types::EdgeHint;
use rustc_hir::def::DefKind;
use rustc_middle::ty::TyCtxt;
use rustc_span::def_id::DefId;

use crate::capture::edge_emit;
use crate::index::Index;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum RelationTemplate {
    ParentContains,
    ParentAssocItem,
    ImplFor,
    ImplRef,
}

fn relation_templates(def_kind: DefKind) -> &'static [RelationTemplate] {
    match def_kind {
        DefKind::Impl { .. } => &[RelationTemplate::ParentContains, RelationTemplate::ImplFor, RelationTemplate::ImplRef],
        DefKind::AssocFn | DefKind::AssocTy | DefKind::AssocConst => &[RelationTemplate::ParentContains, RelationTemplate::ParentAssocItem],
        _ => &[RelationTemplate::ParentContains],
    }
}

fn push_parent_contains(edges: &mut Vec<EdgeHint>, tcx: TyCtxt<'_>, def_id: DefId, id_u32: u32, index: &Index) -> Option<u32> {
    let parent = tcx.opt_parent(def_id)?;
    let pid = *index.def_to_node.get(&parent)?;
    let parent_u32 = pid.index() as u32;
    edge_emit::push_contains(edges, parent_u32, id_u32);
    Some(parent_u32)
}

fn maybe_push_parent_assoc_item(edges: &mut Vec<EdgeHint>, tcx: TyCtxt<'_>, def_id: DefId, parent_u32: Option<u32>, id_u32: u32) {
    let Some(parent) = tcx.opt_parent(def_id) else {
        return;
    };
    if !matches!(tcx.def_kind(def_id), DefKind::AssocFn | DefKind::AssocTy | DefKind::AssocConst) {
        return;
    }
    if !matches!(tcx.def_kind(parent), DefKind::Trait | DefKind::Impl { .. }) {
        return;
    }
    let Some(src) = parent_u32 else {
        return;
    };
    edge_emit::push_assoc_item(edges, src, id_u32);
}

fn maybe_push_impl_for(edges: &mut Vec<EdgeHint>, tcx: TyCtxt<'_>, def_id: DefId, id_u32: u32, index: &Index) {
    let self_ty = tcx.type_of(def_id).instantiate_identity();
    let Some(adt_def_id) = self_ty.ty_adt_def().map(|adt| adt.did()) else {
        return;
    };
    let Some(&struct_node) = index.def_to_node.get(&adt_def_id) else {
        return;
    };
    edge_emit::push_impl_for(edges, id_u32, struct_node.index() as u32);
}

fn maybe_push_impl_ref(edges: &mut Vec<EdgeHint>, tcx: TyCtxt<'_>, def_id: DefId, id_u32: u32, index: &Index) {
    let Some(&trait_node) = tcx.impl_opt_trait_ref(def_id).and_then(|eb| index.def_to_node.get(&eb.skip_binder().def_id)) else {
        return;
    };
    edge_emit::push_impl_ref(edges, id_u32, trait_node.index() as u32);
}

pub fn project_relations(tcx: TyCtxt<'_>, def_id: DefId, index: &Index) -> Vec<EdgeHint> {
    let Some(&id) = index.def_to_node.get(&def_id) else {
        return Vec::new();
    };
    let mut edges = Vec::new();
    let id_u32 = id.index() as u32;
    let templates = relation_templates(tcx.def_kind(def_id));
    let mut parent_u32: Option<u32> = None;

    for template in templates {
        match template {
            RelationTemplate::ParentContains => {
                parent_u32 = push_parent_contains(&mut edges, tcx, def_id, id_u32, index);
            }
            RelationTemplate::ParentAssocItem => {
                maybe_push_parent_assoc_item(&mut edges, tcx, def_id, parent_u32, id_u32);
            }
            RelationTemplate::ImplFor => {
                maybe_push_impl_for(&mut edges, tcx, def_id, id_u32, index);
            }
            RelationTemplate::ImplRef => {
                maybe_push_impl_ref(&mut edges, tcx, def_id, id_u32, index);
            }
        }
    }

    edges
}

